package br.com.adminpool.controller;
import br.com.adminpool.model.*; import br.com.adminpool.repository.*; import java.math.BigDecimal; import java.math.RoundingMode; import java.util.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/salarios") public class SalarioController {
 private final FuncionarioRepository funcionarios; private final PiscinaRepository piscinas; private final CobrancaRepository cobrancas;
 public SalarioController(FuncionarioRepository f,PiscinaRepository p,CobrancaRepository c){funcionarios=f;piscinas=p;cobrancas=c;}
 @GetMapping public List<Map<String,Object>> listar(Authentication auth){boolean gestor=auth.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_GESTOR"));return funcionarios.findAll().stream().filter(f->gestor||f.getUsuario().getLogin().equalsIgnoreCase(auth.getName())).map(f->{var ps=piscinas.findAll().stream().filter(p->p.getResponsavel()!=null&&p.getResponsavel().getId().equals(f.getId())).toList();var ids=ps.stream().map(p->p.getCliente().getId()).collect(java.util.stream.Collectors.toSet()); BigDecimal recebido=cobrancas.findAll().stream().filter(c->c.getStatus()==StatusCobranca.PAGO&&ids.contains(c.getCliente().getId())).map(CobrancaMensal::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add); BigDecimal salario=recebido.multiply(f.getPercentualMensalidade()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);return Map.of("funcionario",f,"piscinas",ps.size(),"clientes",ids.size(),"recebido",recebido,"salario",salario);}).toList();}
}
